/* A successful deployment is the release floor, even if an old publisher rewrites the game. */
const MINIMUM='1.4.1';
function version(text){const m=/\bVERSION\s*=\s*['"](\d+\.\d+\.\d+)['"]/.exec(text);if(!m)throw Error('Game version missing or invalid.');return m[1];}
function compare(a,b){const x=a.split('.').map(Number),y=b.split('.').map(Number);for(let i=0;i<3;i++)if(x[i]!==y[i])return x[i]>y[i]?1:-1;return 0;}
function check(candidate,previous){for(const floor of [MINIMUM,...previous])if(compare(candidate,floor)<0)throw Error('Blocked game downgrade: '+candidate+' is older than '+floor+'. Use the latest game files. The live game has been kept.');}
async function main(){const fs=require('fs'),candidate=version(fs.readFileSync('echoes_below/index.html','utf8'));check(candidate,[]);const repo=process.env.GITHUB_REPOSITORY,token=process.env.GITHUB_TOKEN;if(!repo||!token)throw Error('Release validation requires GitHub workflow credentials.');async function api(route){const r=await fetch('https://api.github.com/repos/'+repo+route,{headers:{Authorization:'Bearer '+token,Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'}});if(!r.ok)throw Error('Cannot verify release history: HTTP '+r.status);return r.json();}
const runs=await api('/actions/workflows/deploy.yml/runs?status=success&branch=main&per_page=20');const previous=[];for(const sha of [...new Set(runs.workflow_runs.map(r=>r.head_sha))]){const file=await api('/contents/echoes_below/index.html?ref='+encodeURIComponent(sha));previous.push(version(Buffer.from(file.content,'base64').toString()));}check(candidate,previous);console.log('Release '+candidate+' passed downgrade protection.');}
module.exports={version,compare,check};if(require.main===module)main().catch(e=>{console.error(e.message);process.exitCode=1});
